package greet

// Greet returns a greeting for name, or for a stranger when name is empty.
func Greet(name string) string {
	if name == "" {
		name = "stranger"
	}
	return "Hello, " + name + "!"
}

files.greet_test.go:
package greet

import "testing"

func TestGreetName(t *testing.T) {
	if got := Greet("Ada"); got != "Hello, Ada!" {
		t.Fatalf("Greet(Ada) = %q", got)
	}
}

func TestGreetEmpty(t *testing.T) {
	if got := Greet(""); got != "Hello, stranger!" {
		t.Fatalf("Greet(\"\") = %q", got)
	}
}

files.greet.mjs:
// greet returns a greeting for name, or for a stranger when name is empty.
export function greet(name) {
  return `Hello, ${name === "" ? "stranger" : name}!`;
}

files.greet.test.mjs:
import test from "node:test";
import assert from "node:assert/strict";
import { greet } from "./greet.mjs";

test("greet names the caller", () => {
  assert.equal(greet("Ada"), "Hello, Ada!");
});

test("greet greets a stranger for an empty name", () => {
  assert.equal(greet(""), "Hello, stranger!");
});
